export{ModalEmpleadoCtrl};function ModalEmpleadoCtrl($scope,mS,$uibModalInstance,tS,params){function onInit(){mS.getData("post","/TipoIdentificacion/ReadTipoIdentificacion",{tipoValidacion:"V"}).then(response=>{$scope.tipoIdentificaciones=response.data,$scope.data.idTipoIdentificacion=$scope.tipoIdentificaciones[0].idTipoIdentificacion,$scope.data.identificacion=$scope.tipoIdentificaciones[0].identificacion}),params&&params.idEmpleado>0&&($scope.tipoRegistro=2,$scope.data=params)}$scope.tipoRegistro=1,$scope.data={},onInit(),$scope.onChangeTipoIdentificacion=function(){$scope.data.identificacion=$scope.tipoIdentificaciones.find(item=>item.idTipoIdentificacion===$scope.data.idTipoIdentificacion).identificacion},$scope.saveAndUpdate=function(){try{const titulo=1===$scope.tipoRegistro?"Guardar":"Actualizar";if(!($scope.data.idTipoIdentificacion>0))return void tS.toastr("warning","Seleccione el Tipo Identificación",titulo);if(!$scope.data.nroIdentificacion)return void tS.toastr("warning","Ingrese Nro. de Identificación",titulo);if(1===$scope.tipoRegistro){if(!$scope.data.nombre)return void tS.toastr("warning","Ingrese el Nombre",titulo);if(!$scope.data.apellido)return void tS.toastr("warning","Ingrese el Apellido",titulo);$scope.data.nombreCompleto=$scope.data.nombre+" "+$scope.data.apellido}if(2===$scope.tipoRegistro&&!$scope.data.nombreCompleto)return void tS.toastr("warning","Ingrese el Nombre Completo",titulo);const url=1===$scope.tipoRegistro?"/Empleado/Post":"/Empleado/Put?idEmpleado="+$scope.data.idEmpleado;showLoader(),mS.getData("post",url,$scope.data).then(response=>{hideLoader(),"0"!=response.id?"1"==response.id&&(tS.toastr("success",response.message,response.titleSms),$uibModalInstance.close(response)):tS.toastr("warning",response.message,response.titleSms)})}catch(error){hideLoader(),toastr.error(error)}},$scope.closeModal=function(){$uibModalInstance.close()}}ModalEmpleadoCtrl.$inject=["$scope","mainService","$uibModalInstance","toastService","params"];